        MAP.put(UrlObfuscator.decode(new int[] { 203, 177, 133, 46, 65, 79, 63, 30, 244, 222, 245, 154, 119, 69, 50, 26, 226, 210, 253, 144, 124, 67, 33, 26, 224, 194, 185, 157, 39, 78, 40, 1, 225, 219, 240, 207, 104, 107, 83, 49 }, 164), F450);
        MAP.put(UrlObfuscator.decode(new int[] { 212, 167, 128, 119, 69, 35, 64, 249, 218, 187, 196, 122, 69, 61, 0, 239, 203, 183, 204, 97, 78, 50, 59, 17, 235, 221, 246, 138, 117, 77, 48, 31, 251, 153, 178, 130, 97, 29, 35, 15, 248, 194, 168, 130, 108, 90, 104, 17, 242, 211, 236, 174, 96, 85, 81, 61, 21, 249, 201, 244, 147, 107 }, 181), F451);
